"""Build a local review artifact from frozen audit records. No model calls or experiments."""
from pathlib import Path
import csv, hashlib, html, json
from collections import Counter
from urllib.parse import quote
R=Path(__file__).resolve().parent.parent; O=R/'review-2026-10-04'
read=lambda n:json.loads((O/n).read_text())
H=lambda x:html.escape(str(x),quote=True)
inv=read('inventory.json');root=read('root-review.json');guide=read('methodology-guide-review.json');reg=read('regrowth-avalon-review.json');ep=read('evidence-projects-review.json')
findings=root['findings']+guide['findings']+reg['findings']+ep['findings']
addinv=read('addendum-inventory.json')
addenda=[read(n) for n in ['addendum-root.json','addendum-theseus.json','addendum-healing.json','addendum-immune.json']]
for d in addenda:findings.extend(d.get('findings',[]))
for f in findings:
 if f['id']=='EP-06':f['status']='partially resolved in late export: Theseus source and complete Healing pilot03 now reviewed; immune reproducibility gaps remain. See dated addendum.'
 if f['id']=='EP-11':f['status']='later DEPLOYMENT documentation clarifies separate plan and implementation revisions; no changed scientific design found'
 if f['id']=='EP-09':f['status']='historical limitation preserved; pilot03 now measures immediate erasure, with a small integrated effect. See ADD-H findings.'
findings.sort(key=lambda f:(f['severity'],f['project'],f['id']))
coverage= root['coverage']+guide['coverage']+reg['coverage']+read('evidence-projects-coverage.json')
by={x['path']:x for x in coverage}; assert len(by)==len(coverage)==inv['count']
assert set(by)=={x['path'] for x in inv['files']}
for x in inv['files']:
 c=by[x['path']];c['sha256']=x['sha256'];c['bytes']=x['bytes'];c['mode']=c.get('mode',c.get('review_mode',c.get('review_depth','see detailed review')))
 c['finding_ids']=sorted(set(c.get('finding_ids',[])+[f['id'] for f in findings if any(e['path']==x['path'] for e in f['evidence'])]))
for c in coverage:c['review_snapshot_utc']=inv['snapshot_utc']
initial_coverage=coverage
extra=[]
for d in addenda:
 cv=d.get('coverage',[])
 if not cv and d.get('coverage_file'):cv=read(Path(d['coverage_file']).name)
 extra.extend(cv)
extra_by={c['path']:c for c in extra}
assert len(extra_by)==len(extra)==len(addinv['files']), (len(extra_by),len(extra),len(addinv['files']))
assert set(extra_by)=={c['path'] for c in addinv['files']}
for x in addinv['files']:
 c=extra_by[x['path']];c['sha256']=x['sha256'];c['bytes']=x['bytes'];c['review_snapshot_utc']=addinv['snapshot_utc'];c['mode']=c.get('mode',c.get('review_mode',c.get('review_depth','see addendum review')))
 c['finding_ids']=[f['id'] for f in findings if any(e['path']==x['path'] for e in f['evidence'])]
versions=initial_coverage+extra
(O/'coverage-versions.json').write_text(json.dumps(versions,indent=2,ensure_ascii=False)+'\n')
coverage=list({c['path']:c for c in versions}.values());coverage_count=len(coverage)
(O/'coverage.json').write_text(json.dumps(sorted(coverage,key=lambda c:c['path']),indent=2,ensure_ascii=False)+'\n')
with (O/'coverage.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['path','bytes','sha256_at_snapshot','review_mode','findings','review_snapshot_utc'])
 for c in sorted(coverage,key=lambda c:c['path']):w.writerow([c['path'],c['bytes'],c['sha256'],c['mode'],','.join(c['finding_ids']),c['review_snapshot_utc']])
(O/'findings.json').write_text(json.dumps(findings,indent=2,ensure_ascii=False)+'\n')
# Live workspace drift is visible, never silently substituted for reviewed evidence.
skip={'.git','node_modules','.venv','__pycache__','review-2026-10-04'}
current={str(p.relative_to(R)):p for p in R.rglob('*') if p.is_file() and not any(s in skip for s in p.relative_to(R).parts)}
old={x['path']:x for x in inv['files']}
added=sorted(set(current)-set(old)); missing=sorted(set(old)-set(current));changed=[]
for k in sorted(set(current)&set(old)):
 digest=hashlib.sha256(current[k].read_bytes()).hexdigest()
 if digest!=old[k]['sha256']:changed.append({'path':k,'snapshot_sha256':old[k]['sha256'],'current_sha256':digest})
review_edits=['README.md','agent-experiment-guide/AGENT-LIFECYCLE.md','agent-experiment-guide/AGENT-LIFECYCLE-RESEARCH.md','agent-experiment-guide/research/agent-lifecycle-sources.json','agent-experiment-guide/README.md','agent-experiment-guide/GUIDE.md','agent-experiment-guide/HARNESS.md','agent-experiment-guide/LITERATURE.md','agent-experiment-guide/PACKAGE-MANIFEST.json','dossier-src/build.py','dossier-src/prism.py','swarm-ecology-dossier.html','regrowth-200/DEVELOPMENT.md','regrowth-200/PROTOCOL.md']
drift=dict(snapshot_utc=inv['snapshot_utc'],added_after_snapshot=added,missing_since_snapshot=missing,changed_since_snapshot=changed,review_authored_paths=review_edits,interpretation='The initial and addendum inventories define reviewed evidence. Later changes listed separately remain outside the frozen numerical review. Review-authored documents are separately QA-checked; archived experiment manifests are unchanged.')
latest={x['path']:x for x in inv['files']}
latest.update({x['path']:x for x in addinv['files']})
drift['final_review_snapshot_utc']=addinv['snapshot_utc']
drift['unreviewed_added_after_final_snapshot']=sorted(set(current)-set(latest)-set(review_edits))
drift['unreviewed_changed_after_final_snapshot']=[k for k in sorted(set(current)&set(latest)-set(review_edits)) if hashlib.sha256(current[k].read_bytes()).hexdigest()!=latest[k]['sha256']]
(O/'workspace-drift.json').write_text(json.dumps(drift,indent=2)+'\n')
counts=Counter(f['severity'] for f in findings)

def link(path,label=None):
 href=path if path.startswith('https://') else '../'+quote(path,safe='/')
 return '<a href="'+H(href)+'">'+H(label or path)+'</a>'
def table(headers,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+H(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,title,body,kicker=''):
 return f'<section id="{id}" class="section"><p class="eyebrow">{H(kicker)}</p><h2>{H(title)}</h2>{body}</section>'
